package com.andye.warmod.radar.station;import java.util.*;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.level.ChunkPos;public final class RadarStationChunkTicketManager {private static final Map<ServerLevel,Map<ChunkPos,Integer>>REFS=new WeakHashMap<>();private static final Map<ServerLevel,Map<UUID,Set<ChunkPos>>>STATIONS=new WeakHashMap<>();private RadarStationChunkTicketManager(){}public static synchronized boolean register(ServerLevel level,UUID id,net.minecraft.core.BlockPos centre){var map=STATIONS.computeIfAbsent(level,k->new LinkedHashMap<>());if(!map.containsKey(id)&&map.size()>=RadarStationConstants.MAX_RADAR_STATIONS_PER_LEVEL)return false;if(map.containsKey(id))return true;Set<ChunkPos>chunks=new HashSet<>();for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++)chunks.add(new ChunkPos((centre.getX()+x)>>4,(centre.getZ()+z)>>4));var refs=REFS.computeIfAbsent(level,k->new HashMap<>());for(var c:chunks){int n=refs.getOrDefault(c,0);if(n==0)level.getChunkSource().addTicketWithRadius(RadarStationChunkTicketType.STATION,c,0);refs.put(c,n+1);}map.put(id,Set.copyOf(chunks));return true;}public static synchronized void unregister(ServerLevel level,UUID id){var map=STATIONS.get(level);if(map==null)return;Set<ChunkPos>chunks=map.remove(id);var refs=REFS.get(level);if(chunks!=null&&refs!=null)for(var c:chunks){int n=refs.getOrDefault(c,0);if(n<=1){refs.remove(c);level.getChunkSource().removeTicketWithRadius(RadarStationChunkTicketType.STATION,c,0);}else refs.put(c,n-1);}if(map.isEmpty())STATIONS.remove(level);if(refs!=null&&refs.isEmpty())REFS.remove(level);}public static synchronized void clear(){for(var e:REFS.entrySet())for(var c:e.getValue().keySet())e.getKey().getChunkSource().removeTicketWithRadius(RadarStationChunkTicketType.STATION,c,0);REFS.clear();STATIONS.clear();}}